INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Netzwerkknoten immer physische Geräte sein müssen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch virtuelle Knoten möglich"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Netzwerkknoten für ein IT-Netzwerk auswähle?', 3, '[{"text": "Funktionalität", "correct": true, "because": "Bestimmt Rolle"}, {"text": "Schnellste Installation", "correct": false, "because": "Leistung zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Netzwerkknoten gibt es?', 5, '[{"text": "Router", "correct": true, "because": "Leitet Daten"}, {"text": "Switches", "correct": true, "because": "Verbindet Geräte"}, {"text": "Büromöbel", "correct": false, "because": "Kein Knoten"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Netzwerkknoten kann Daten weiterleiten. b) Er ist immer ein Endgerät.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht immer Endgerät"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Netzwerkknoten für ein IT-System plane?', 4, '[{"text": "Netzwerkrolle", "correct": false, "because": "Bestimmt Funktion"}, {"text": "Datenrate", "correct": false, "because": "Beeinflusst Leistung"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Netzwerkknoten immer ein physisches Gerät sein muss?', 2, '[{"text": "Nein", "correct": true, "because": "Virtuelle Knoten möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Netzwerkknoten in einem IT-Netzwerk?', 3, '[{"text": "Datenkommunikation", "correct": true, "because": "Ermöglicht Übertragung"}, {"text": "Schnellste Installation", "correct": false, "because": "Funktion zählt"}, {"text": "Weniger Knoten", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale sind bei Netzwerkknoten entscheidend?', 5, '[{"text": "Verbindungsfähigkeit", "correct": true, "because": "Ermöglicht Kommunikation"}, {"text": "Datenverarbeitung", "correct": true, "because": "Verarbeitet Daten"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Netzwerkknoten kann ein Router sein. b) Er ist immer ein Endgerät wie ein PC. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht nur Endgeräte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Netzwerkknoten effektiv einzusetzen?', 4, '[{"text": "Netzwerkprotokolle", "correct": false, "because": "Ermöglichen Kommunikation"}, {"text": "Anschlüsse", "correct": false, "because": "Verbinden Geräte"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Netzwerkknoten immer Endgeräte?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Router, Switches"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Netzwerkknoten?', 4, '[{"text": "Datenübertragung", "correct": true, "because": "Ermöglichen Kommunikation"}, {"text": "Netzwerkeffizienz", "correct": true, "because": "Optimieren Verkehr"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Netzwerkknoten nur physische Geräte sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch virtuelle Knoten"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Netzwerkknoten für ein IT-System auszuwählen?', 3, '[{"text": "Funktionalität", "correct": true, "because": "Bestimmt Rolle"}, {"text": "Günstigster Preis", "correct": false, "because": "Leistung wichtiger"}, {"text": "Bunte Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Netzwerkknoten kann Daten weiterleiten. b) Er hat immer eine MAC-Adresse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht alle haben MAC"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Netzwerkknoten?', 5, '[{"text": "Datenrate", "correct": true, "because": "Beeinflusst Leistung"}, {"text": "Verbindungstyp", "correct": true, "because": "Bestimmt Einsatz"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Netzwerkknoten für ein IT-System auswähle?', 3, '[{"text": "Bandbreite", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Kompatibilität", "correct": false, "because": "Sichert Funktion"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Netzwerkknoten immer mit einer MAC-Adresse ausgestattet?', 3, '[{"text": "Nein", "correct": true, "because": "Nicht alle haben MAC"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Netzwerkknoten nur Daten empfangen können?', 2, '[{"text": "Nein", "correct": true, "because": "Auch senden, weiterleiten"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
